# Offline command completion, generated from the native help inventory.
_neboc_complete() {
    local word
    COMPREPLY=()
    while IFS= read -r word; do COMPREPLY+=("$word"); done < <(compgen -W '--help --version abi-report add-import api-diff assemble bench bootstrap bug-report build cache change-review check check-docs compatibility-report compiler-bench compiler-memory compiler-profile compiler-report completion-corpus completion-debug conformance conformance-manifest crypto-audit db diagnostic-schema diagnostics diverse-build docs doctor dump emit-asm emit-asm|build emit-bpf emit-hir|emit-lir emit-interface emit-object emit-wasm examples exit-codes explain firmware fix format fuzz fuzz-source geometry-check hover|signature-help|definition imports incremental-report init|add|remove|resolve|vendor|package|audit interface link lint lsp meta-check meta-expand migrate migrate-imports migration-check minimize-ice modernize module-check module-graph module-info module-init-report navigation-corpus nebo-1.0-readiness numeric-report object-build object-verify operator-info optimize-explain organize-imports performance-gate portable-sbom portable-test prelude-report probabilistic-report profile project-report protocol provenance-verify query-report reactive-report refactor references release rename repl reproducibility-report roadmap-closeout route-bench runtime-report scientific-bench sdk security-report self-contained-audit selftest serve server simulation-replay solve source-optimize stdlib symbol-index symbols test test-docs timings toolchain-report trust-manifest verify warnings wasm-inspect workflow' -- "${COMP_WORDS[COMP_CWORD]}")
}
complete -F _neboc_complete neboc
